import{_ as o}from"./plugin-vue_export-helper-DlAUqK2U.js";import{r as n,c as r,d as a,b as e,o as c}from"./app-DF9ah-uV.js";const i={},s=e("p",null,"你好，这一节我们来聊一聊 PmHub 的技术选型。",-1),l=e("p",null,"背景 PmHub 并不是一个 从 0 开始造轮子的项目，用户权限基础服务我们没有重新开发，我们认为一个优秀的系统一定是站在巨人的肩膀上的，在若依基础后台管理功能的基础上做的二开，比如，我们加了 mybatis-plus，路由设计、自定义权限注解等基础能力的升级。",-1),p=e("p",null,"不瞒大家说，目前国内大部分中小型公司、科研机构、学校组织的后台管理系统的底层都是基于若依开发的，所以 PmHub 也不想重复造轮子，我们希望给大家展示的是更多的可以体现在简历中的技术亮点，而非基础重复的功能，否则浪费了双方的时间就得不偿失了。",-1),m=e("p",null,"整体介绍 系统架构 基于项目管理系统的分层特点，将整个系统的架构分为：前端展示曾、网关控制层、服务应用层、基础服务层、存储技术层、支撑服务层、运行资源层",-1),u=e("figure",null,[e("img",{src:"https://cdn.tobebetterjavaer.com/stutymore/20240807225939.png",alt:"干货教程",tabindex:"0",loading:"lazy"}),e("figcaption",null,"干货教程")],-1);function d(h,g){const t=n("VPBanner");return c(),r("div",null,[s,l,p,m,u,a(t,{title:"以下为付费内容",content:"为了让大家“无痛”掌握 PmHub，我们耗费了巨大心血，从项目立项，到代码编写、测试、部署，再到教程撰写，前后足足经历了 5 个月的时间，并且我们还计划再用 3 个月的时间，为大家再更新 60 篇预计 25 万字的硬核教程。希望大家能支持我们一把。",logo:"https://cdn.tobebetterjavaer.com/stutymore/image-20240725123037.png",actions:[{text:"加入二哥编程星球",link:"https://laigeoffer.cn/zsxq/"},{text:"了解 PmHub 付费教程",link:"https://laigeoffer.cn/pmhub/learn/",type:"default"}]})])}const y=o(i,[["render",d],["__file","tech-select-design.html.vue"]]),f=JSON.parse('{"path":"/pmhub/architecture/tech-select-design.html","title":"PmHub 技术选型与设计（👍强烈推荐）","lang":"zh-CN","frontmatter":{"title":"PmHub 技术选型与设计（👍强烈推荐）","shortTitle":"PmHub技术选型与设计","date":"2024-08-07T06:38:56.000Z","categories":["PmHub","开篇词"],"requiresAuth":true,"description":"PmHub 拆分了用户、流程、项目管理、认证等 4 个微服务，整合了 Redis 缓存、RocketMQ 消息队列、Docker 容器、Jenkins 自动化部署、Spring Security 安全框架、Nacos 服务注册和发现、Spring Boot Actuator 服务监控、Skywalking 链路追踪、Sentinel 熔断降级、Seata 分布式事务、Vue 前端框架等互联网开发中需要用到的绝大多数主流技术栈。","head":[["meta",{"name":"keywords","content":"PmHub,Spring  Cloud,微服务,AI,知识星球,沉默王二,二哥的Java进阶之路,二哥的编程星球,Java进阶之路,编程,Java,IT,计算机专业,付费专栏,实战项目,分布式"}],["meta",{"property":"og:url","content":"https://laigeoffer.cn/pmhub/architecture/tech-select-design.html"}],["meta",{"property":"og:site_name","content":"来个offer"}],["meta",{"property":"og:title","content":"PmHub 技术选型与设计（👍强烈推荐）"}],["meta",{"property":"og:description","content":"PmHub 拆分了用户、流程、项目管理、认证等 4 个微服务，整合了 Redis 缓存、RocketMQ 消息队列、Docker 容器、Jenkins 自动化部署、Spring Security 安全框架、Nacos 服务注册和发现、Spring Boot Actuator 服务监控、Skywalking 链路追踪、Sentinel 熔断降级、Seata 分布式事务、Vue 前端框架等互联网开发中需要用到的绝大多数主流技术栈。"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:image","content":"https://cdn.tobebetterjavaer.com/stutymore/20240807225939.png"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"article:author","content":"苍何&沉默王二"}],["meta",{"property":"article:published_time","content":"2024-08-07T06:38:56.000Z"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"PmHub 技术选型与设计（👍强烈推荐）\\",\\"image\\":[\\"https://cdn.tobebetterjavaer.com/stutymore/20240807225939.png\\"],\\"datePublished\\":\\"2024-08-07T06:38:56.000Z\\",\\"dateModified\\":null,\\"author\\":[{\\"@type\\":\\"Person\\",\\"name\\":\\"苍何&沉默王二\\",\\"url\\":\\"https://github.com/laigeoffer\\"}]}"]]},"headers":[],"git":{"createdTime":null,"updatedTime":null,"contributors":[]},"readingTime":{"minutes":2.12,"words":636},"filePathRelative":"pmhub/architecture/tech-select-design.md","localizedDate":"2024年8月7日"}');export{y as comp,f as data};
